        "explanation": "Correct: (b). Extra water leaves pores when it evaporates, weakening the hardened concrete. (a) is wrong: \"Nothing happens\" — extra water is the most common cause of weak concrete. (c) is wrong: \"The concrete gets stronger\" — extra water weakens concrete. (d) is wrong: \"The concrete sets faster\" — extra water usually slows setting."
