        "answer": 2,
        "explanation": "Correct: (c). Bleed water appears as the mix settles; finishing must wait until it evaporates. (a) is wrong: \"Rain on the slab\" — rain is weather, not bleed water. (b) is wrong: \"Curing water\" — curing water is applied after finishing. (d) is wrong: \"Water added to the mix\" — mix water is added at the plant; bleed water rises after placing."
