        "answer": 2,
        "explanation": "Correct: (c). Concrete that dries early stops gaining strength and develops a weak, dusty surface. (a) is wrong: \"It cures faster\" — drying is not curing. (b) is wrong: \"Nothing happens\" — early drying is a major cause of weak concrete. (d) is wrong: \"It gets stronger\" — early drying weakens concrete."
