        "explanation": "Correct: (d). Isolation joints let the slab move without pushing against walls and columns. (a) is wrong: \"A joint in the middle of a slab\" — that is a control joint. (b) is wrong: \"A decorative saw cut\" — isolation joints are functional separation joints. (c) is wrong: \"A joint that is filled with concrete\" — isolation joints are filled with compressible material, not concrete."
